/** The Sphinx card: "1 point. 2 per type beyond three, else 1." */
const BASE_POINTS = 1;
const FREE_TYPES = 3;
const POINTS_PER_TYPE_BEYOND_FREE = 2;
const POINTS_WITHIN_FREE_TYPES = 1;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const distinctMonsters = (army: Card[]): Set<string> =>
  new Set(army.map((card) => card.monster));

/** Types the Sphinx surveys — every distinct monster except the Sphinx itself. */
const countTypesBesidesSphinx = (army: Card[]): number =>
  distinctMonsters(army).size - 1;

const typeBonus = (typesBesidesSphinx: number): number =>
  typesBesidesSphinx > FREE_TYPES
    ? POINTS_PER_TYPE_BEYOND_FREE * (typesBesidesSphinx - FREE_TYPES)
    : POINTS_WITHIN_FREE_TYPES;

export const scoreArmy = (army: Card[]): number => {
  const sphinxCount = army.filter(isSphinx).length;
  return sphinxCount * (BASE_POINTS + typeBonus(countTypesBesidesSphinx(army)));
};

